 * Runs the instant-runoff count. Returns the list of rounds counted, each
 * with every continuing candidate's vote count, the number of exhausted
 * ballots, and the name eliminated at the end of that round (or null),
 * together with the winner's name or null when nobody reached a majority.
 */

export function runElection({ candidates, ballots }) {
  let continuing = new Set(candidates)
  const rounds = []
  let winner = null

  while (true) {
    const counts = {}
    for (const c of continuing) counts[c] = 0
    let activeTotal = 0
    let exhausted = 0

    for (const ballot of ballots) {
      const choice = ballot.names.find((name) => continuing.has(name))
      if (choice === undefined) {
        exhausted += ballot.count
      } else {
        counts[choice] += ballot.count
        activeTotal += ballot.count
      }
    }

    const round = { counts, exhausted, eliminated: null }
    rounds.push(round)

    if (activeTotal === 0) {
      winner = null
      break
    }

    const majority = [...continuing].find((c) => counts[c] * 2 > activeTotal)
    if (majority !== undefined) {
      winner = majority
      break
    }

    const eliminated = pickEliminated(continuing, counts, rounds)
    round.eliminated = eliminated
    continuing.delete(eliminated)
  }

  return { rounds, winner }
}

function pickEliminated(continuing, counts, rounds) {
  const minVotes = Math.min(...[...continuing].map((c) => counts[c]))
  let tied = [...continuing].filter((c) => counts[c] === minVotes)

  while (tied.length > 1) {
    let narrowed = false
    for (const round of rounds) {
      const values = tied.map((c) => round.counts[c])
      if (new Set(values).size > 1) {
        const m = Math.min(...values)
        tied = tied.filter((c) => round.counts[c] === m)
        narrowed = true
        break
      }
    }
    if (!narrowed) break
  }

  if (tied.length === 1) return tied[0]
  return tied.slice().sort().pop()
}
"}

