/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */

import { parseElection } from './parse.js'
import { runElection } from './election.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exitCode = 2
}

function formatRound(round, index) {
  const entries = Object.entries(round.counts).sort((a, b) => {
    if (b[1] !== a[1]) return b[1] - a[1]
    return a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0
  })
  const parts = entries.map(([name, votes]) => `${name}=${votes}`)
  parts.push(`exhausted=${round.exhausted}`)
  const lines = [`round ${index + 1}: ${parts.join(' ')}`]
  if (round.eliminated !== null) lines.push(`eliminated ${round.eliminated}`)
  return lines
}

function main(argv, input) {
  const mode = argv[0]
  if (argv.length !== 1 || (mode !== 'rounds' && mode !== 'tally')) {
    fail('usage: cli.js rounds|tally')
    return
  }

  let election
  try {
    election = parseElection(input)
  } catch (err) {
    fail(err.message)
    return
  }

  const { rounds, winner } = runElection(election)
  const output = []

  if (mode === 'rounds') {
    for (let i = 0; i < rounds.length; i++) {
      output.push(...formatRound(rounds[i], i))
    }
  } else {
    output.push(`rounds ${rounds.length}`)
  }
  output.push(winner === null ? 'no winner' : `winner ${winner}`)

  process.stdout.write(output.join('\n') + '\n')
}

function readStdin() {
  return new Promise((resolve, reject) => {
    const chunks = []
    process.stdin.on('data', (chunk) => chunks.push(chunk))
    process.stdin.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')))
    process.stdin.on('error', reject)
  })
}

readStdin()
  .then((input) => main(process.argv.slice(2), input))
  .catch((err) => {
    process.stderr.write(`error: ${err.message}\n`)
    process.exitCode = 2
  })
"}

